INSERT INTO etl_meta.register_targets (id, register_id, target_schema, target_table, union_id, source_id, load_mode, upsert_keys, pre_load_sql, is_active, created_at, include_columns, post_load_sql, priority, target_role, parent_target_id) VALUES (80, 62, 'public', 'sales', NULL, 256, 'upsert', '{recorder,recorder_type}', NULL, true, '2026-06-18 06:32:30.699167', '{vidoperatsii,doc_sale_uid,updated_at,podrazdelenie,zakaz_type,recorder_type,recorder,dogovor_uid,otvetstvennyy_uid,kontragent,is_posted,organizatsiya_uid,zakaz_uid,period,sklad,doc_sale_type,doc_number}', '-- dim_otvetstvennyy: stub + резолв id (тираж guid→id, 2026-07-29)
INSERT INTO public.dim_otvetstvennyy (guid)
SELECT DISTINCT s.otvetstvennyy_uid
FROM   public.sales s
WHERE  s.otvetstvennyy_id IS NULL
  AND  s.otvetstvennyy_uid IS NOT NULL
  AND  s.otvetstvennyy_uid <> ''00000000-0000-0000-0000-000000000000''::uuid
ON CONFLICT (guid) DO NOTHING;

UPDATE public.sales s
SET    otvetstvennyy_id = d.id
FROM   public.dim_otvetstvennyy d
WHERE  s.otvetstvennyy_uid = d.guid
  AND  s.otvetstvennyy_id IS NULL;

