UPDATE public.sales_positions p SET kachestvo_id = d.id FROM public.dim_kachestvo d
WHERE p.kachestvo = d.guid AND p.kachestvo_id IS NULL;
-- upsert обновляет строки по (recorder, recorder_type, line_no), но не удаляет те,
-- которых больше нет в источнике (кейс 87000001933: было 8 строк, стало 4 —
-- строки 5-8 висели с устаревшими 47 млн). Внутри документа все актуальные строки
-- получают одинаковый etl_updated_at последней загрузки; строки со старым временем —
-- исчезнувшие. Окно 60 мин ограничивает работу документами текущего прогона.
DELETE FROM public.sales_positions p
USING (
    SELECT recorder, recorder_type, MAX(etl_updated_at) AS last_load
    FROM public.sales_positions
    WHERE (recorder, recorder_type) IN (
        SELECT DISTINCT recorder, recorder_type
        FROM public.sales_positions
        WHERE etl_updated_at > timezone(''Asia/Almaty'', now()) - interval ''60 minutes''
    )
    GROUP BY recorder, recorder_type
) t
WHERE p.recorder = t.recorder
  AND p.recorder_type = t.recorder_type
  AND p.etl_updated_at < t.last_load;

-- Удаление строк, ИСЧЕЗНУВШИХ из документа при перепроведении в 1С (2026-07-30).
-- upsert обновляет строки по (recorder, recorder_type, line_no), но не удаляет те,
-- которых больше нет в источнике (кейс 87000001933: было 8 строк, стало 4 —
-- строки 5-8 висели с устаревшими 47 млн). Внутри документа все актуальные строки
-- получают одинаковый etl_updated_at последней загрузки; строки со старым временем —
-- исчезнувшие.
--   • окно 60 мин — ограничивает работу документами текущего прогона (индекс по etl_updated_at);
--   • зазор 30 мин — защита от грязного чтения: при NOLOCK можно поймать документ
--     в момент перепроведения и увидеть частичный набор строк. Разрыв внутри одного
--     прогона (секунды/минуты) под правило не подпадает, реальный ретро-случай
--     (строки загружены дни назад) — подпадает.
DELETE FROM public.sales_positions p
USING (
    SELECT recorder, recorder_type, MAX(etl_updated_at) AS last_load
    FROM public.sales_positions
    WHERE (recorder, recorder_type) IN (
        SELECT DISTINCT recorder, recorder_type
        FROM public.sales_positions
        WHERE etl_updated_at > timezone(''Asia/Almaty'', now()) - interval ''60 minutes''
    )
    GROUP BY recorder, recorder_type
) t
WHERE p.recorder = t.recorder
  AND p.recorder_type = t.recorder_type
  AND p.etl_updated_at < t.last_load - interval ''30 minutes'';', 1, 'fact', 80);
